xf:submission.script:

grid1.removeAll();
var dataXML = e.responseBody;
grid1.setXML(dataXML);

var mpSbmtStatCd="";
var mpMenuOpenSttsCd="";
var bfCheckDocYn="";

btnApyUnable.hide();		//일시적적용불가버튼
btnBfCheck.hide();			//사전검토버튼
btnMenuOpen.hide();			//메뉴오픈버튼
btnAddMenuOpen.hide();		//메뉴오픈추가버튼
btnOpenRslt.hide();			//오픈결과버튼
btnChngRqDoc.hide();		//변경요청서작성버튼

if(grid1.getRowCount() == 0){
	btnBfCheck.show();
}else{
	if(grid1.getCellData(0,"docSeq")=="TEMP_DATA"){
		if(grid1.getRowCount() == 1){
			btnBfCheck.show();
		}else{
			mpSbmtStatCd=grid1.getCellData(1,"mpSbmtStatCd");				//문서제출상태코드
			mpMenuOpenSttsCd=grid1.getCellData(1,"mpMenuOpenSttsCd");		//메뉴오픈요청상태코드
			bfCheckDocYn=grid1.getCellData(1,"bfCheckDocYn");				//사전검토문서존재여부
		}
	}else{
		mpSbmtStatCd=grid1.getCellData(0,"mpSbmtStatCd");				//문서제출상태코드
		mpMenuOpenSttsCd=grid1.getCellData(0,"mpMenuOpenSttsCd");		//메뉴오픈요청상태코드
		bfCheckDocYn=grid1.getCellData(0,"bfCheckDocYn");				//사전검토문서존재여부
	}
	if(mpSbmtStatCd=="01"){
		if(bfCheckDocYn=="Y"){
			btnApyUnable.show();
			btnAddMenuOpen.show();
			if(mpMenuOpenSttsCd=="09"){
				btnOpenRslt.show();
			}
		}else{
			//보여줄 버튼 없음 사전검토요청 상태
		}
	}else if(mpSbmtStatCd=="02"){
		if(bfCheckDocYn=="Y"){
			btnApyUnable.show();
			btnAddMenuOpen.show();
		}else{
			//보여줄 버튼 없음 사전검토중인 상태
		}
	}else if(mpSbmtStatCd=="03"){
		if(bfCheckDocYn=="Y"){
			btnApyUnable.show();
			if(mpMenuOpenSttsCd=="08"){
				btnOpenRslt.show();
				btnChngRqDoc.show();
			}else if(mpMenuOpenSttsCd=="09"){
				btnMenuOpen.show();
				btnOpenRslt.show();
			}else if(mpMenuOpenSttsCd=="07"){
				btnOpenRslt.show();
			}else if(mpMenuOpenSttsCd=="10"){
				btnChngRqDoc.show();
				btnOpenRslt.show();
			}else if(mpMenuOpenSttsCd=="00"){
				btnMenuOpen.show();
			}
		}else{
			//있을수 없음 검토완료 된 건이 존재하는데 사전검토여부가 N이라는게
		}
	}else if(mpSbmtStatCd=="04"){
		if(bfCheckDocYn=="Y"){
			btnApyUnable.show();
			btnChngRqDoc.show();
		}else{
			btnBfCheck.show();
		}
	}else if(mpSbmtStatCd=="13"){		//추가제출상태
		btnApyUnable.show();
		if(bfCheckDocYn=="Y"){
			if(mpMenuOpenSttsCd=="07"||mpMenuOpenSttsCd=="09"){
				btnOpenRslt.show();
			}else if(mpMenuOpenSttsCd=="08"||mpMenuOpenSttsCd=="10"){
				btnOpenRslt.show();
				btnChngRqDoc.show();
			}
		}else{
			//있을수 없음 추가제출은 변경제출후 건임...
		}
	}
}

head.script:


		imports("uiplugin.popup");

		grid1.insertRow();
		grid1.insertRow();
		grid1.insertRow();

			/********************************************
			* Parameter
			********************************************/
			var menu=WebSquare.net.getParameter("menu");
			var mgEnpCd="";
			var emplyrId="";
			var currentDate="";
			var printDate="";
			var selectRow="";

			/********************************************
			* session
			********************************************/
			function doProccess(){
				fn_init();
			}

			/********************************************
			* window.onLoad()
			********************************************/
			function fn_init(){
				mgEnpCd = WebSquare.ModelUtil.getInstanceValue("session/map/map/insttCode/@value");
				emplyrId = WebSquare.ModelUtil.getInstanceValue("session/map/map/emplyrId/@value");
				currentDate = WebSquare.ModelUtil.getInstanceValue("session/map/map/currentDate/@value");
				printDate = currentDate.substr(0,4)+"년 "+currentDate.substr(4,2)+"월 "+currentDate.substr(6,2)+ "일";

				WebSquare.ModelUtil.setInstanceValue("select/map/plPeri/@value","1차");
				WebSquare.ModelUtil.setInstanceValue("select/map/mgEnpCd/@value",mgEnpCd);
				WebSquare.ModelUtil.executeSubmission("selectEnpSbmtMpDocList"); //제출현황 목록 조회
				var rowCnt=grid1.getRowCount();
				var docSeq="";
				for(var i=0;i<rowCnt;i++){
					docSeq=grid1.getCellData(i,"docSeq");
					if(docSeq!=null && docSeq.length > 2){
						selectRow=i;
						break;
					}
				}
				output15555.setValue(docSeq=="TEMP_DATA"?"(문서번호 : 작성중)":"(문서번호 : "+docSeq+")");
				WebSquare.ModelUtil.setInstanceValue("select/map/docSeq/@value",docSeq);
				WebSquare.ModelUtil.setInstanceValue("select/map/plPeri/@value",grid1.getCellData(selectRow,"plPeri"));
				WebSquare.ModelUtil.setInstanceValue("select/map/itgClsCd/@value","MG002");
				WebSquare.ModelUtil.setInstanceValue("select/map/mgAtc3Nm/@value","7");
				WebSquare.ModelUtil.executeSubmission("selectSbmtMpDoc"); //제출문서 목록 조회
				WebSquare.ModelUtil.executeSubmission("selectPobSeqList"); //사업장 목록 조회
				WebSquare.ModelUtil.executeSubmission("selectVeriMpInfo"); //모니터링 계획서 검증 정보 조회

			}

			/********************************************
			* 그리드 - 관리화면
			********************************************/
			function mgAtc1NmFunction(data){
				var msg = "";
				if(data != ""){
					msg += "<a href=javascript:fnLocLinkMove('" + data + "');>";
					msg += "<img src='/images/button/btnImage_link.gif' alt='링크'/>";
					msg += "</a>";
				}
				return msg;
			}

			function fnLocLinkMove(data){
				window.location.href="/websquare/websquare.html?w2xPath="+data;
			}

			/********************************************
			* 링크 팝업
			********************************************/
			function linkFunction(data){
				var url = "";
				var retObj = null;
				if(data.indexOf(".sa",1)> 1){
					url = "/ibsheet/iframe.jsp?url=" + data;
					url = url.replace(".sa?menu", ".sa&menu");
					retObj = window.showModalDialog(url, window, "dialogWidth:1030px; dialogHeight:850px; scroll:auto; resizable:yes;");
				}else{
					url = "/websquare/websquare.html?w2xPath=" + data;
					retObj = retObj = window.showModalDialog(url, window, "dialogWidth:1000px; dialogHeight:700px; scroll:auto; resizable:yes;");
				}
				if(retObj == null){}
			}

			/********************************************
			* 그리드 - 보고서
			********************************************/
			function printFunction(data){
				var msg = "";
				if(data != ""){
					msg += "<img src='/images/button/btnImage_view.gif' alt='보고서'/>";
				}
				return msg;
			}

			/********************************************
			* 검사기관지정 팝업 호출
			********************************************/
			function openVeriInstApp(){
				imports("uiplugin.popup");
				var hash = new WebSquare.collection.Hashtable();
				hash.put("mgEnpCd",mgEnpCd);
				hash.put("veriInstRgNo",veriMpDocGrd.getCellData(0,"veriInstRgNo"));
				hash.put("mpOpenBdt",veriMpDocGrd.getCellData(0,"mpOpenBdt"));
				hash.put("mpOpenEdt",veriMpDocGrd.getCellData(0,"mpOpenEdt"));
				if(veriMpDocGrd.getCellData(0,"veriReqDt")!="-"&&veriMpDocGrd.getCellData(0,"veriDocSeq")=="-"){
					hash.put("readOnlyVeriEnpYn","Y");
				}else{
					hash.put("readOnlyVeriEnpYn","N");
				}
				var paramXml = hash.toString();
				var options = {
							   id : "veriInstApp",
							   type : "window",
							   width: "700px",
							   height: "260px",
							   top: "100px",
							   left: "500px",
							    popupName : "모니터링 계획서 제출현황",
							    modal : true,
							    useIFrame : false,
							    style : "",
							    resizable : true,
							    status : false,
							    menubar : false,
							    scrollbars : true,
							    title : false,
							    xml: paramXml,
							    srcData: "",
							    destData: ""
							};
				WebSquare.uiplugin.popup.openPopup("/vr/mpa/OGVRMPA000P.xml",options);
			}

			/********************************************
			* MP검증 요청 팝업 호출
			********************************************/
			function openVeriMpDocRq(){
				imports("uiplugin.popup");
