						docSeq = grid1.getCellData(i,"docSeq");
						break;
					}
				}

				hash.put("mgEnpCd",mgEnpCd);
				hash.put("docSeq",docSeq);
				hash.put("corpNm",veriMpDocGrd.getCellData(0,"corpNm"));
