			function fnMpMenuOpenRq(addRqYn){
			    imports("uiplugin.popup");
				var mgEnpCd= grid1.getCellData(0,"mgEnpCd");
				var plPeri = grid1.getCellData(0,"plPeri");
				var docSeq = grid1.getCellData(0,"docSeq");
				var mpSbmtStatCd = grid1.getCellData(0,"mpSbmtStatCd");
				var callPath = "2"; // 1: 주무관청 , 2: 할당대상업체
				var view = "요청";

				if(addRqYn == "X"){
					view="결과";
				}

				if("TEMP_DATA"==docSeq){
					if(addRqYn == "X"){
						docSeq = grid1.getCellData(1,"docSeq");
					}else{
				     	alert("신규작성 상태에서는 MP메뉴 오픈 요청을 하실 수 없습니다.");
				     	return;
				     }
				}

			    var hash = new WebSquare.collection.Hashtable();
				hash.put("mgEnpCd",mgEnpCd);
				hash.put("docSeq",docSeq);
				hash.put("plPeri",plPeri);
				hash.put("mpSbmtStatCd",mpSbmtStatCd);
				hash.put("callPath",callPath);
				hash.put("addRqYn",addRqYn)
				hash.put("view",view);

				var paramXml = hash.toString();

				var options = {
								id : "popup1",
								type : "window",
								width: "700px",
								height: "400px",
								top: "0px",
								left: "0px",
								popupName : "오픈 요청 확인",
							    modal : true,
							    useIFrame : false,
							    style : "",
							    resizable : true,
							    status : false,
							    menubar : false,
							    scrollbars : true,
							    title : false,
							    xml: paramXml,
							    srcData: "",
							    destData: ""
							};
				WebSquare.uiplugin.popup.openPopup("/oe/mpa/OGOEMPA441P.xml",options);
			}

			function fnOpenApyUnablRq(){
				imports("uiplugin.popup");
				var docSeq = "";
				var mgEnpCd= grid1.getCellData(0,"mgEnpCd");
				var plPeri = grid1.getCellData(0,"plPeri");
				var mgEnpCdNm = insttNm;
				var view ="작성";
				var callPath ="2"; //할당대상업체
				if(grid1.getCellData(0,"docSeq") == "TEMP_DATA"){
					docSeq = grid1.getCellData(1,"docSeq");
				}else{
					docSeq = grid1.getCellData(0,"docSeq");
				}
				var insttNm = WebSquare.ModelUtil.getInstanceValue("session/map/map/insttNm/@value");

				if(docSeq=="TEMP_DATA"){
				   docSeq = grid1.getCellData(0,"modDocSeq");
				}
				if(docSeq==null||docSeq==""){
				   alert("모니터링 계획 사전검토서 신청서 제출 후 사용 가능 합니다.");
				   return;
				}

				var hash = new WebSquare.collection.Hashtable();

				hash.put("mgEnpCd",mgEnpCd);
				hash.put("plPeri",plPeri);
				hash.put("docSeq",docSeq);
				hash.put("view",view);
				hash.put("callPath",callPath);
				hash.put("mgEnpCdNm",insttNm);

				var paramXml = hash.toString();

				 var options = {
							   id : "popup4",
							   type : "window",
							   width: "900px",
							   height: "480px",
							   top: "0px",
							   left: "0px",
							    popupName : "모니터링 계획 일시적적용불가 통지서",
							    modal : true,
							    useIFrame : false,
							    style : "",
							    resizable : true,
							    status : false,
							    menubar : false,
							    scrollbars : true,
							    title : false,
							    xml: paramXml,
							    srcData: "",
							    destData: ""
							};
				WebSquare.uiplugin.popup.openPopup("/oe/mpa/OGOEMPA522P.xml",options);
			}

			function onCellClickMpDocList(rowNum,colNum){

				imports("uiplugin.popup");
				var hash = new WebSquare.collection.Hashtable();
				var popupId="";
				var popupName="";
				var url="";
				var pWidth="";
				var pHeight="";

				var mgEnpCd=grid1.getCellData(rowNum,"mgEnpCd");
				var docSeq=grid1.getCellData(rowNum,"docSeq");
				var modDocSeq=grid1.getCellData(rowNum,"modDocSeq");
				var plPeri=grid1.getCellData(rowNum,"plPeri");

				hash.put("mgEnpCd",mgEnpCd);
				hash.put("docSeq",docSeq);
				hash.put("modDocSeq",modDocSeq);
				hash.put("plPeri",plPeri);
				hash.put("callPath","2");
				hash.put("mode","R");
				hash.put("view","보기");

				var colNm = grid1.getColumnID(colNum);

				if(colNm!="mpView"&&colNm!="rqDocView"&&colNm!="rqRlsView"&&colNm!="attFileView"&&colNm!="veriView"){
					return;
				}

				if(grid1.getCellData(rowNum,colNm) == "-"){
					return;
				}

				if(colNm == "mpView"){			//MP열람
					output15555.setValue(docSeq=="TEMP_DATA"?"(문서번호 : 작성중)":"(문서번호 : "+docSeq+")");
					WebSquare.ModelUtil.setInstanceValue("select/map/docSeq/@value",docSeq);
					WebSquare.ModelUtil.setInstanceValue("select/map/plPeri/@value",plPeri);
					selectRow = rowNum;
					WebSquare.ModelUtil.executeSubmission("selectPobSeqList");
					return;
				}else if(colNm == "rqDocView"){	//요청서보기
					var rlsVal=grid1.getCellData(rowNum,"rqDocView");
					if(rlsVal=="변경"){
						popupId="mpRlsRq";
						popupName="변경요청서";
						url="/oe/mpa/OGOEMPA442P.xml";
						pWidth="700px";
						pHeight="700px";
					}else if(rlsVal=="사전"){
						popupId="mpEnnRqDoc";
						popupName="사전검토신청서";
						url="/oe/mpa/OGOEMPA171P.xml";
						pWidth="700px";
						pHeight="380px";
						hash.put("view","보기");
						hash.put("callPath","1");
					}else{
						return;
					}
				}else if(colNm == "rqRlsView"){	//검토결과서보기
					popupId="mpModDocView";
					var rlsVal=grid1.getCellData(rowNum,"rqRlsView");
					if(rlsVal=="시정검토"){
						popupName="시정보완요청";
						url="/oe/mpa/OGOEMPA412P.xml";
						pWidth="700px";
						pHeight="350px";
					}else if(rlsVal=="사전검토"){
						hash.put("mode","R");
						url="/oe/mpa/OGOEMPA411P.xml";
						pWidth="700px";
						pHeight="550px";
					}else if(rlsVal=="추가검토"){
						hash.put("mode","R");
						url="/oe/mpa/OGOEMPA423P.xml";
						pWidth="1100px";
						pHeight="870px";
					}else{
						return;
					}
				}else if(colNm == "attFileView"){	//첨부파일
					var fileId=grid1.getCellData(rowNum,"mpRewAttchFileId");
					getFileDownLoad(fileId);
					return;
				}else if(colNm == "veriView"){		//MP 검증보고서
					if(grid1.getCellData(rowNum,"veriView")=="-") return;
					var veriDocSeq = grid1.getCellData(rowNum,"veriDocSeq");
					var insttNm = WebSquare.ModelUtil.getInstanceValue("session/map/map/insttNm/@value");
					var emplyrNm = WebSquare.ModelUtil.getInstanceValue("session/map/map/emplyrNm/@value");
					var oReport = GetfnParamSet();
		            	oReport.rptname = "vr/mpa/OGVRMPA000R";
