			// 변경요청서
			function fnModMpDocOpen(){
				imports("uiplugin.popup");
				var url = "/oe/mpa/OGOEMPA442P.xml"; // 변경요청서 작성 또는 보기

				var param ="";
				var tmpPlPeri = "";
				var tmpMgEnpCd = "";
				var tmpDocSeq = "";
				var tmpModDocSeq = "";
				var mpSbmtStatCd = "";
				var tmpView = "작성";

				var dataRowNum=0;
				if(grid1.getCellData(0,"docSeq") == "TEMP_DATA"){
					dataRowNum=1;
				}

				tmpPlPeri = grid1.getCellData(dataRowNum,"plPeri");
				tmpMgEnpCd = grid1.getCellData(dataRowNum,"mgEnpCd");
				tmpDocSeq = grid1.getCellData(dataRowNum,"docSeq");
				tmpModDocSeq = grid1.getCellData(dataRowNum,"modDocSeq");
				mpSbmtStatCd = grid1.getCellData(dataRowNum,"mpSbmtStatCd");

				var hash = new WebSquare.collection.Hashtable();

				hash.put("plPeri",tmpPlPeri);
				hash.put("mgEnpCd",tmpMgEnpCd);
				hash.put("docSeq",tmpDocSeq);
				hash.put("modDocSeq",tmpModDocSeq);
				hash.put("view",tmpView);
