			function rexpertOutPut(){
				var oReport = GetfnParamSet();
				var arrayList = grid2.getCheckedIndex(0);

				if(arrayList == ""){
					alert("출력할 데이터가 없습니다.");
					return;
				}

				var oReport = GetfnParamSet();
				var docSeqNmV = "신규작성";
		        var docSeqV = "";
		        var pobNmV = "";
		        var pobSeqV = "";
				docSeqNmV = grid1.getCellData(selectRow,"docSeq");
				docSeqV = grid1.getCellData(selectRow,"docSeq");
				pobNmV = pobSeqList.getText();
				pobSeqV =  pobSeqList.getValue();

				oReport.rptname = "oe/mpa/OGOEMPA000R";
				oReport.param("MG_ENP_CD").value = mgEnpCd;
				oReport.param("PL_PERI").value = grid1.getCellData(selectRow,"plPeri");
				oReport.param("DOC_SEQ").value = docSeqV;
				oReport.param("SERVER_ADDR").value = REX_SOP_SERVER;
				oReport.param("POB_SEQ").value = pobSeqV;

