			function getFileDownLoad(fileId){
				var param = "?atch_file_id=" + fileId + "&file_sn=0";
				var request = "http://master.gir.go.kr/cm/cmb/getBlobFile.do" + param;
				window.open(request);
			}

			/********************************************
             * 작성 또는 보기
             ********************************************/
            function fn_viewAndReg(data){
            	var msg="-";
				if(data == "보기"){
					msg="<img src='/images/button/btnImage_view.gif' alt='보기' style='cursor:pointer;'/>";
				}else if(data == "작성"){
					msg="<img src='/images/button/btnImage_write.gif' alt='작성' style='cursor:pointer;'/>";
				}else if(data == "다운"){
					msg="<img src='/images/button/btnImage_down.gif' alt='다운' style='cursor:pointer;'/>";
				}else if(data == "변경"){
					msg="<img src='/images/button/btnImage_change2.gif' alt='변경요청서' style='cursor:pointer;'/>";
				}else if(data == "첨부"){
					msg="<img src='/images/button/btnImage_file.gif' alt='첨부파일' style='cursor:pointer;'/>";
				}else if(data == "추가검토"){
					msg="<img src='/images/button/btnImage_review2.gif' alt='추가검토결과' style='cursor:pointer;'/>";
				}else if(data == "시정검토"){
					msg="<img src='/images/button/btnImage_rectify2.gif' alt='시정보완요청' style='cursor:pointer;'/>";
				}else if(data == "사전검토"){
					msg="<img src='/images/button/btnImage_beforehand2.gif' alt='사전검토결과' style='cursor:pointer;'/>";
				}else if(data == "조회"){
					msg="<img src='/images/button/btnImage_inquiry.gif' alt='조회' style='cursor:pointer;'/>";
				}else if(data == "사전"){
					msg="<img src='/images/button/btnImage_examination2.gif' alt='사전검토 신청서' style='cursor:pointer;'/>";
				}else if(data == "검증"){
					msg="<img src='/images/button/btnImage_verification.gif' alt='검증보고서' style='cursor:pointer;'/>";
				}
				return msg;
            }

